    fixPrompt: "¿Qué causa el fallo, qué pilares de Well-Architected no se cubrieron y qué cambias para que no se repita?",
    acceptableFixes: ["service principal", "application user", "usuario de aplicacion", "cuenta personal", "connection reference", "referencia de conexion", "solucion", "process", "alerta", "monitor", "reliability", "operational excellence"],
