      context: "Copilot generó para la galería: Filter('Solicitudes TI', Prioridad = \"Alta\" && StartsWith(Trim('Título de Solicitud'), Trim(txtBusqueda.Text)) && Len('Título de Solicitud') > 0). Prioridad es una columna Choice de Dataverse; la tabla tiene 3.000 filas.",
