    symptom: "El lunes, las solicitudes de Colombia se acumulan en 'En análisis' sin score. La DLQ está en 0 y la Logic App no registra ejecuciones desde el viernes. En My flows, el flujo 'Enviar solicitud al buró' aparece como Suspended. Nadie recibió ninguna alerta.",
    fixPrompt: "¿Qué causa el incidente, por qué TEST no lo detectó y qué cambias hoy, en el diseño y en el proceso de cambios?",
    acceptableFixes: ["data policy", "politica de datos", "dlp", "http", "blocked", "bloqueado", "suspended", "suspendido", "adr", "service bus", "cola", "excluido", "paridad", "test", "comite de cambios", "control de cambios", "alerta", "monitoreo"],
