    implementation: "function validarFechas(executionContext) {\n  var formContext = executionContext.getFormContext();\n  var inicio = formContext.getAttribute(\"sit_fechainicio\").getValue();\n  var fin = formContext.getAttribute(\"sit_fechafin\").getValue();\n  var control = formContext.getControl(\"sit_fechafin\");\n  if (fin < inicio) {\n    control.setNotification(\"La fecha fin no puede ser anterior a la fecha inicio\");\n  }\n}\n\nLearn (setNotification): \"Setting an error notification on a control will block the form from saving.\"\nLearn (getValue): \"The value may be null.\"\nnull < new Date(\"2026-11-10\") → true",
    symptom: "Tras corregir la fecha fin a una válida, el aviso rojo sigue junto al campo y el formulario no guarda; al borrar la fecha fin aparece el aviso aunque no hay nada que comparar.",
    fixPrompt: "¿Por qué pasa y qué cambiarías en la función?",
