    symptom: "El job termina en verde aunque SIT_CLIENT_SECRET no está definido en el repositorio, y el log muestra el client secret completo, mientras que los valores que sí son secretos de GitHub aparecen como ***.",
    fixPrompt: "¿Por qué el job funciona sin el secreto y por qué se ve en el log? ¿Qué haces primero y qué cambias en el código?",
