    multiple: true,
    options: [
      { id: "diseno-antes-copilot", label: "Humano diseña: antes de pedirle el cambio a Copilot se escribe el criterio (qué monto dispara el aviso, a quién llega, qué pasa con 10,000 exactos) y cómo se probará en Test", consequence: "Correcto: es la misma etapa 1, aunque no haya código. Sin ese criterio, nadie puede decir en Test si el flujo quedó bien.", score: 1 },
      { id: "checker-es-estatico", label: "CI valida: el solution checker hace análisis estático contra reglas de buenas prácticas; en modo Block solo detiene la importación ante problemas críticos, así que no comprueba la regla de los 10,000", consequence: "Correcto: según Learn, Block cancela la importación cuando hay problemas de severidad crítica. Es un linter, no una prueba de tu regla de negocio.", score: 1 },
      { id: "aprobacion-delegada", label: "Humano aprueba: se configura una aprobación antes de Prod (por ejemplo, un despliegue delegado que espera la aprobación de una persona autorizada), y quien aprueba revisa la evidencia de Test contra el criterio", consequence: "Correcto: Learn documenta las aprobaciones de pipelines mediante despliegues delegados. La aprobación vale por lo que la persona revisa, no por el clic.", score: 1 },
      { id: "mismo-artefacto", label: "Pipelines despliega en Prod el mismo artefacto que pasó por Test, sin volver a exportarlo, así que no se puede saltar la etapa de Test", consequence: "Correcto: Learn indica que el mismo artefacto recorre las etapas en orden y que el sistema impide modificarlo, para que nadie se salte QA ni la aprobación.", score: 1 },
      { id: "checker-reemplaza-pruebas", label: "Si el solution checker no encuentra problemas críticos, el cambio ya está validado y se puede omitir la prueba en Test", consequence: "No: el checker no sabe nada de tu regla de negocio. Un flujo que avisa con 1,000 en vez de 10,000 puede pasar el checker sin un solo problema.", score: 0 },
      { id: "copilot-aprueba", label: "Como Copilot generó el cambio, se le puede pedir que resuma el flujo y usar ese resumen como aprobación", consequence: "Un resumen generado por IA ayuda a revisar, pero no reemplaza la etapa 4: la aprobación es de una persona que compara la evidencia con el criterio.", score: 0 },
    ],
    correctOptionIds: ["diseno-antes-copilot", "checker-es-estatico", "aprobacion-delegada", "mismo-artefacto"],
    hints: [
      { id: "h1", content: "Busca, para cada etapa (diseña, implementa, valida, aprueba), qué pieza de Power Platform la cumple y qué no puede saber esa pieza." },
      { id: "h2", content: "El solution checker es análisis estático: detecta patrones problemáticos, no comprueba que el aviso salga con el monto correcto. Pipelines garantiza el orden de las etapas y el mismo artefacto; la aprobación la da una persona." },
      { id: "h3", content: "Son cuatro las correctas: el criterio antes de Copilot, el checker como análisis estático que en Block solo detiene lo crítico, la aprobación antes de Prod revisada contra la evidencia de Test, y el mismo artefacto en todas las etapas." },
    ],
    relatedModuleIds: [51, 54],
    relatedLabIds: ["LAB-051", "LAB-053"],
    tags: ["ia", "flujo-humano-ia-ci", "transferencia", "pipelines", "solution-checker"],
