    symptom: "El perfil se llama sit-practica-dev, pero su Friendly Name es 'Contoso (default)' y la URL no coincide con la de su ambiente Developer; pac solution list muestra soluciones ajenas.",
    fixPrompt: "¿Qué pasó y con qué comandos lo corriges y lo confirmas antes del import?",
